<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$search = trim((string) ($_GET['q'] ?? ''));
$statement = $pdo->prepare('SELECT id, title, slug, category, duration, level, image, status, updated_at FROM courses WHERE CONCAT_WS(" ", title, slug, category) LIKE :search ORDER BY id DESC');
$statement->execute(['search' => '%' . $search . '%']); $courses = $statement->fetchAll(); admin_header('Courses', 'courses/index.php');
?><div class="d-flex flex-wrap gap-2 justify-content-between mb-3"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search courses..."><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-search"></i></button></form><a href="create.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Add Course</a></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Course</th><th>Category</th><th>Duration / Level</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($courses as $course): ?><tr><td><strong><?= e($course['title']) ?></strong><small class="d-block text-secondary"><?= e($course['slug']) ?></small></td><td><?= e($course['category']) ?></td><td><small><?= e($course['duration']) ?><br><?= e($course['level']) ?></small></td><td><span class="badge text-bg-<?= $course['status'] ? 'success' : 'secondary' ?>"><?= $course['status'] ? 'Active' : 'Inactive' ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= e($course['id']) ?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?= e($course['id']) ?>">Delete</a></td></tr><?php endforeach; ?><?php if (!$courses): ?><tr><td colspan="5" class="text-center text-secondary py-5">No courses found.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>